import { describe, expect, test } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { DEPARTMENTS, INTERIORS, REFERENCE } from '../src/config/sceneConfig';
import type { DeptId } from '../src/config/sceneConfig';

// Evidence snapshot generated by scripts/department-interiors-deep-audit.mjs. These are per-room
// audit-integrity tests, NOT a fidelity pass: the report explicitly records that the stage is open.
const root = path.resolve(process.cwd(), '../../docs/design/main-workspace/greybox/visual-fidelity/reconstruction/01-department-interiors/deep-audit/after-whiteboard-content');
const audit = JSON.parse(readFileSync(path.join(root, 'audit.json'), 'utf8')) as {
  reference: { sha256: string; width: number; height: number };
  current: { sha256: string; browserErrors: string[]; browserSnapshot: { viewport: number[]; dpr: number; camera: { position: number[]; quaternion: number[] } } };
  departments: Array<{ id: DeptId; image: { width: number; height: number; maeRgb8: number; ssimGray8x8: number }; roi: { fullRectNoExclusions: boolean; rawPairwiseOverlapPixels: number }; catalogue: { sourceItemCount: number; sourceItemsWithoutRuntimeGeometryTag: Array<{ id: string; kind: string }> }; geometry: { roomFootprintCornerProjection: Array<{ deltaPx: number[] }> } }>;
};
const expectedIds: DeptId[] = ['DEPT-01','DEPT-02','DEPT-03','DEPT-04','DEPT-05','DEPT-06','DEPT-07'];
const result = new Map(audit.departments.map(d => [d.id, d]));
function pngDimensions(file: string): [number, number] {
  const bytes = readFileSync(file);
  if (bytes.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a') throw new Error(`${file} is not PNG`);
  return [bytes.readUInt32BE(16), bytes.readUInt32BE(20)];
}

describe('Department Interiors independent evidence checks (not acceptance)', () => {
  test('one locked source and a fresh full-resolution HOME-camera render were used', () => {
    expect(audit.reference.sha256).toBe(REFERENCE.sha256);
    expect([audit.reference.width, audit.reference.height]).toEqual([REFERENCE.width, REFERENCE.height]);
    expect(audit.current.browserSnapshot.viewport).toEqual([REFERENCE.width, REFERENCE.height]);
    expect(audit.current.browserSnapshot.dpr).toBe(1);
    expect(audit.current.browserErrors).toEqual([]);
  });

  test.each(expectedIds)('%s: independent full-ROI image, inventory, geometry and evidence artifacts', id => {
    const d = result.get(id)!;
    const directory = path.join(root, 'sections', id.toLowerCase());
    const referenceCrop = pngDimensions(path.join(directory, 'reference-crop.png'));
    const currentCrop = pngDimensions(path.join(directory, 'current-render.png'));
    const overlay = pngDimensions(path.join(directory, 'overlay-50.png'));
    const difference = pngDimensions(path.join(directory, 'difference.png'));
    expect(referenceCrop).toEqual([d.image.width, d.image.height]);
    expect(currentCrop).toEqual([d.image.width, d.image.height]);
    expect(overlay).toEqual([d.image.width, d.image.height]);
    expect(difference).toEqual([d.image.width, d.image.height]);
    expect(d.roi.fullRectNoExclusions).toBe(true);
    expect(d.catalogue.sourceItemCount).toBe(INTERIORS.filter(i => i.dept === id).length);
    expect(d.catalogue.sourceItemsWithoutRuntimeGeometryTag).toEqual([]);
    expect(d.image.maeRgb8).toBeGreaterThanOrEqual(0);
    expect(d.image.maeRgb8).toBeLessThanOrEqual(255);
    expect(d.image.ssimGray8x8).toBeGreaterThanOrEqual(-1);
    expect(d.image.ssimGray8x8).toBeLessThanOrEqual(1);
    expect(d.geometry.roomFootprintCornerProjection).toHaveLength(4);
    for (const corner of d.geometry.roomFootprintCornerProjection) {
      expect(Math.hypot(...corner.deltaPx)).toBeLessThan(0.5);
    }
    expect(DEPARTMENTS.some(dept => dept.id === id)).toBe(true);
  });
});
